class IGOFrontEnd {
  char pad[1492];
  bool replay_mode;
public:
  void ShowMenuBackground(bool);
  void OnReplayStart() { ShowMenuBackground(false); replay_mode = true; }
};
struct PauseMenuSystem { char pad[148]; bool replay_mode; };
struct FEManager { IGOFrontEnd *IGO; PauseMenuSystem *pms; };
extern FEManager frontendmanager;

class camera {};
struct ReplayVtable {
  char pad[1600];
  short adjust;
  short unused;
  void (*reset_fn)(void *);
};
class replay_camera {
  char pad[8];
  ReplayVtable *table;
public:
  void reset() {
    ReplayVtable *v = table;
    v->reset_fn((char *)this + v->adjust);
  }
};
class world_dynamics_system {
  char pad[344];
  replay_camera *replay_cam_ptr;
public:
  replay_camera *get_replay_cam_ptr() { return replay_cam_ptr; }
};
extern world_dynamics_system *g_world_ptr;

class game {
  char pad[188];
  int active_player;
public:
  int get_active_player() { return active_player; }
  void set_player_camera(int, camera *);
};
class app {
  char pad[16];
  game *the_game;
public:
  static app *instance;
  static app *inst() { return instance; }
  game *get_game() { return the_game; }
};

class os_developer_options {
  char pad[72];
  int flags;
public:
  enum { FLAG_NO_AUDIO = 1 };
  static os_developer_options *instance;
  static os_developer_options *inst() { return instance; }
  bool is_flagged(int flag) const { return (flags & flag) != 0; }
};

class DemoModeManager { public: bool inDemoMode(); };
extern DemoModeManager dmm;
void nslUnpauseAllSounds();

class Track {
  int source;
  int sound;
  bool paused;
  char songName[30];
  char artistName[30];
public:
  void Unpause();
};
class MusicListing {
  int totalSources;
  int current;
  Track sources[50];
  int currentSoundId;
  bool successfulLastPlay;
  int order[50];
  bool enabled[50];
public:
  void unpause() { sources[order[current]].Unpause(); }
};
class MusicMan {
  float volume;
  int inited;
  bool paused;
public:
  static MusicMan *instance;
  static MusicMan *inst() { return instance; }
  MusicListing musicTrack;
  void unpause() { if (paused) { paused = false; musicTrack.unpause(); } }
};

class KSReplay {
  void *vptr;
public:
  int bch, sfr, brd;
private:
  unsigned seed;
  int status;
  float playtime;
  float lastPlaytime;
  bool slomo;
  bool fastforward;
  bool prepareSlomo;
  bool prepareNormal;
public:
  bool Done();
  void Play();
  void Pause(bool);
  void RestoreNextFrame(float);
  void Resume();
};

void KSReplay::Resume()
{
  if(Done())
  {
    Play();
    return;
  }

	frontendmanager.IGO->OnReplayStart();
  frontendmanager.pms->replay_mode = true;

	Pause(false);
  slomo         = false;
  fastforward   = false;
  prepareSlomo      = false;
  prepareNormal     = false;

  g_world_ptr->get_replay_cam_ptr()->reset();

  replay_camera *replayCam = g_world_ptr->get_replay_cam_ptr();
  app::inst()->get_game()->set_player_camera(app::inst()->get_game()->get_active_player(), (camera*)replayCam);

	if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
	{
    if(dmm.inDemoMode())
		  nslUnpauseAllSounds();
		MusicMan::inst()->unpause();
	}

  RestoreNextFrame(0.0f);
}
